import {useState, useCallback,useRef,useEffect} from 'react';
import { useHistory } from 'react-router-dom/cjs/react-router-dom.min';

export const useHttpClient =()=>{

    //handle loading state and error
    const [isLoading,setIsLoading]=useState(false);
    const [error,setError]=useState();

    //to make sure we are handling state of correct page
    const activeHttpRequests=useRef([]);

    //after clicking error modal we wanna redirect to home page
    const hist=useHistory();

    const sendRequest=useCallback(
        async(url,method='GET',body=null,headers={})=>{
            //page is loading initially
            setIsLoading(true);

            const httpAbortCtrl=new AbortController();
            activeHttpRequests.current.push(httpAbortCtrl);

            try{
                //fetch url and set method, body and headers, and abort signal
                const response=await fetch(url,{method,body,headers,signal:httpAbortCtrl.signal});

                const responseData=await response.json();

                //remove old requests
                activeHttpRequests.current = activeHttpRequests.current.filter(
                reqCtrl => reqCtrl !== httpAbortCtrl
                );

                //if we have some connection error here
                if(!response.ok){
                    throw new Error(responseData.message);
                }
                setIsLoading(false);
                //return response data in json
                return responseData;
            }catch(err){
                //remove old requests
                activeHttpRequests.current = activeHttpRequests.current.filter(
                reqCtrl => reqCtrl !== httpAbortCtrl
                );
                setIsLoading(false);
                setError(err.message);
                throw err;
            }

    },[]);

    const clearError=()=>{
        setError(null);
        hist.push('/');
    };

    //cleanup function to make sure we dont send request to page we closed
    useEffect(() => {
        return () => {
            activeHttpRequests.current.forEach(abortCtrl => abortCtrl.abort());
        };
    }, []);

    return {isLoading,error,sendRequest,clearError};

};

