import React from "react";
import { useEffect, useState} from "react";


import PlaceList from "../components/PlaceList";

import { useParams,useHistory } from "react-router-dom/cjs/react-router-dom.min";

import { useHttpClient } from "../../shared/hooks/http-hook";

import ErrorModal from "../../shared/components/UIElements/ErrorModal";
import LoadingSpinner from "../../shared/components/UIElements/LoadingSpinner";

const UserPlaces = ()=>{
    const [loadedPlaces,setLoadedPlaces]=useState();

    const {isLoading,error,sendRequest,clearError}=useHttpClient();


    const userId=useParams().userId;
    const hist=useHistory();


    useEffect(()=>{
        const fetchPlaces=async()=>{
            try{
                const responseData=await sendRequest(`${process.env.REACT_APP_BACKEND_URL_API}/places/user/${userId}`);
                setLoadedPlaces(responseData.places);
            }catch(err){
            }
        };

        fetchPlaces();
    },[sendRequest,userId]);



    //the aftermath of deleting a place from mongo
    const placeDeletedHandler=deletedPlaceId=>{
        setLoadedPlaces(//in our places array j filter out the deleted id
            prevPlaces=>prevPlaces.filter(place=>place.id!==deletedPlaceId)
        );
        //redirect user to home page after deleting
        hist.push('/');

    };

    return<React.Fragment>
        <ErrorModal error={error} onClear={clearError}/>
        {isLoading&&(
            <div className="center">
                <LoadingSpinner/>
            </div>
        )}{/*only run this if not loading, if places exist to show */}
        {!isLoading&&loadedPlaces&&<PlaceList items={loadedPlaces} onDeletePlace={placeDeletedHandler}/>}
    </React.Fragment>

}

export default UserPlaces;